    note: "■ 這間是什麼\n文京區向丘2丁目、東大前站徒步3分的<b>新築一戶建</b>——從設計、施工到銷售都是我們公司自己來的自社物件。地上3層、土地106.74㎡・建物177.36㎡的4LDK，現況已完成，2026年10月上旬交屋。\n■ 亮點一：<b>誠之小學校學區</b>\n文京區最有人氣的小學被家長叫做「<a href=\"bunkyo-3s1k-elementary-schools.html\">3S1K</a>」——誠之、昭和、千駄木、窪町，這間就在其中名氣最大的<b>誠之小學校</b>學區，中學是區立第六中學校。西片・向丘這一帶本來就是安靜的高級住宅區，東大本鄉校區就在旁邊，住戶裡醫師、律師、研究者的比例高，補習班與升學資源也集中。很多家庭是為了學區才搬進來的，所以這一區的房子一向不太等人。\n（3S1K 是長年在教育與房地產市場形成的印象，不是政府公布的排名；學區劃分也可能調整，實際請以文京區公所最新公告為準。）\n■ 亮點二：近站又有內建車庫\n東大前3分、白山11分、根津12分，三站三條線。車庫直接收在屋子裡（約6.4m×2.9m），下雨天上下車不用淋到；文京區這個地段能同時做到近站、獨棟、車位不外租的，本來就不多。\n■ 格局與規格\n設備是平檯廚房、洗碗機、瓦斯衣物乾燥機（乾太くん）、全熱交換第一種換氣、噴塗隔熱、SECOM居家保全、瓦斯溫水地暖、電動車充電插座、制震阻尼器。耐震等級2、ZEH水準、隔熱性能第5級，省能標示三顆星，預估年水電瓦斯費約19.7萬円。Flat 35 房貸（フラット35）的35S・A方案適合證明書預計取得。\n■ 自社物件，問到底都可以\n房子是我們自己蓋的，設計怎麼想的、材料用什麼、施工過程如何，我這邊都問得到，不必經過第三家。想看房或先試算貸款，加LINE跟我說一聲，我用中文一步一步陪你走完。"
